// ============================================================
// 1) Debezium PostgreSQL SOURCE connector (Kafka Connect config)
// PUT /connectors/products-source-connector/config
// ============================================================
{
  "name": "products-source-connector",
  "config": {
    "connector.class": "io.debezium.connector.postgresql.PostgresConnector",
    "database.hostname": "postgres.internal",
    "database.port": "5432",
    "database.user": "debezium",
    "database.password": "${file:/secrets/pg-creds.properties:password}",
    "database.dbname": "catalog",
    "topic.prefix": "catalog",
    "plugin.name": "pgoutput",
    "slot.name": "products_slot",
    "publication.name": "products_pub",
    "publication.autocreate.mode": "filtered",
    "table.include.list": "public.products",
    "snapshot.mode": "initial"
    // NOTE: decimal.handling.mode is intentionally absent here -> falls back to the Debezium default "precise"
  }
}

// ============================================================
// 2) PostgreSQL schema for the source table (as deployed)
// ============================================================
CREATE TABLE public.products (
  id          BIGINT PRIMARY KEY,
  sku         TEXT NOT NULL,
  name        TEXT NOT NULL,
  price       NUMERIC(10, 2) NOT NULL,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- REPLICA IDENTITY is left at its default (DEFAULT = primary key columns only),
-- so a DELETE event's "before" image will not include non-key columns such as price.

// ============================================================
// 3) Elasticsearch index mapping for the products index
// ============================================================
PUT /products
{
  "mappings": {
    "properties": {
      "id":         { "type": "long" },
      "sku":        { "type": "keyword" },
      "name":       { "type": "text" },
      "price":      { "type": "double" },
      "updated_at": { "type": "date" }
    }
  }
}

// ============================================================
// 4) Elasticsearch SINK connector (Kafka Connect config)
// PUT /connectors/products-es-sink-connector/config
// ============================================================
{
  "name": "products-es-sink-connector",
  "config": {
    "connector.class": "io.confluent.connect.elasticsearch.ElasticsearchSinkConnector",
    "topics": "catalog.public.products",
    "connection.url": "http://elasticsearch:9200",
    "type.name": "_doc",
    "key.ignore": "false",
    "schema.ignore": "true",
    "behavior.on.null.values": "delete",
    "write.method": "upsert"
  }
}

// ============================================================
// 5) Operational state of the replication slot (currently in effect)
// ============================================================
-- postgresql.conf on this instance:
--   max_slot_wal_keep_size = -1   (default: unlimited WAL retention for any slot)
--
-- No alerting rule exists for:
--   pg_current_wal_lsn() - (SELECT confirmed_flush_lsn FROM pg_replication_slots WHERE slot_name = 'products_slot')
-- and nothing pages on-call if the Kafka Connect worker running
-- products-source-connector has been down or paused past a fixed time threshold.
-- If the consumer stalls, the slot 'products_slot' keeps every unconsumed WAL segment
-- on disk indefinitely, growing linearly until the volume backing PostgreSQL fills up.
